"""Bounded Mac first-mining-flight declarations; never execute original code."""
import copy
from .declaration_layouts import recognize
from .scenery_population import import_symbol

def extract_first_flight(mach, arrival, departure, environment, world):
    if mach.architecture!='x86_64':return {}
    try:
        if departure['scope']!='first_station_departure' or not environment or not world:return {}
        origin=arrival['provenance']['actor']
        if origin['bytes']!=315:return {}
        anchor=mach.text['address']+origin['offset']-mach.slice_offset-mach.text['offset']
        proof=recognize(mach,origin['offset'],[LAYOUTS,MAC_ALTERNATE])
        if not proof:return {}
        imports=MAC_IMPORTS if proof['yaw_matrix_dispatch']['bytes']==MAC_ALTERNATE['yaw_matrix_dispatch'][2] else IMPORTS
        for symbol,delta in imports.items():
            if import_symbol(mach,anchor+delta)!=symbol.encode('ascii'):return {}
        result=copy.deepcopy(VALUES);result['provenance']=proof
        return result
    except (KeyError,TypeError,IndexError,ValueError,OverflowError):return {}

